import { cachedFetchScopeOf } from '../shared/cached-fetch-storage'
import { setCachedFetchOwner } from '../composables/useCachedFetch'
import { computed, defineNuxtPlugin, useNuxtApp, watch } from '#imports'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore virtual module generated by this module's `setup()`
import { useUserSession } from '#ui/optional'

/** `useState` keys of the areas' bootstraps (`loadBootstrap`), as Nuxt stores them in the payload. */
const BOOTSTRAP_STATE = '$sui:bootstrap:'

// The responses `useCachedFetch` remembers belong to the signed-in user: when they sign out or another user signs in,
// they are forgotten (in memory and in the app's storage), and so are the areas' bootstraps (`loadBootstrap`), so the
// next pages load what belongs to the new visitor. Only with `@frigear-nu/auth` installed. After Auth's client-mode
// plugin, which restores the session: the owner at startup is then known before `@frigear-nu/mobile` reads the stored
// responses of that owner.
export default defineNuxtPlugin({
  name: 'ui:cached-fetch-owner',
  // A plugin of another module, not among this module's own plugin names when it is type-checked alone. A literal, so
  // Nuxt reads it at build time.
  // eslint-disable-next-line @typescript-eslint/ban-ts-comment
  // @ts-ignore
  dependsOn: ['auth-client'],
  setup() {
    if (!useUserSession) return
    const nuxtApp = useNuxtApp()
    const { user } = (useUserSession as () => { user: { value: unknown } })()
    const owner = computed(() => cachedFetchScopeOf((user.value as { id?: unknown } | null | undefined)?.id))

    // The first owner is only recorded: what is in memory now (the server's payload) is already theirs.
    setCachedFetchOwner(owner.value, { keep: true })
    watch(owner, (next) => {
      nuxtApp.runWithContext(() => setCachedFetchOwner(next))
      const state = nuxtApp.payload.state as Record<string, unknown>
      for (const key of Object.keys(state)) if (key.startsWith(BOOTSTRAP_STATE)) state[key] = null
    })
  },
})
